import logging

from statuses import REMINDED, TO_CALL
from texts import reminder_text

logger = logging.getLogger(__name__)

LEADS = {
    1: {"name": "Alice", "phone": "+33600000001", "status": TO_CALL, "city": "Lyon"},
    2: {"name": "Bruno", "phone": "+33600000002", "status": REMINDED, "city": "Nantes"},
}


def leads_to_call():
    """Leads still waiting for a call, oldest first."""
    return sorted(lead_id for lead_id, lead in LEADS.items() if lead["status"] == TO_CALL)


def send_reminder(lead_id, sender):
    """Sends the call reminder of one lead; returns True when the sender accepted it."""
    lead = LEADS[lead_id]
    logger.debug("reminder for lead %r", lead)
    accepted = sender(lead["phone"], reminder_text(lead["name"], lead["city"]))
    if accepted:
        lead["status"] = REMINDED
    return accepted

